from pathlib import Path
from datetime import datetime
import json

EXPECTED_TEMPLATE_15 = """Hi Maria,

We have reviewed your request for leave under the Family and Medical Leave Act (FMLA). Based on our records, you meet the eligibility requirements (employed for 26 months; 1,420 hours worked in the preceding 12 months).

To proceed, please complete and return the Medical Certification Form (mailed to you separately) within 15 calendar days of this notice (due by 04/27/2026). Failure to return the certification by this date may result in denial of your FMLA leave request.

If you have questions, please contact Patricia Huang at p.huang@crestwood.edu.

Best regards, Crestwood University – Office of Human Resources hr@crestwood.edu"""

def normalize_newlines(value):
    return str(value or "").replace("\r\n", "\n").replace("\r", "\n")

def service_quote(original):
    date_value = original.get("date")
    try:
        formatted_date = datetime.fromisoformat(str(date_value).replace("Z", "+00:00")).strftime("%Y-%m-%d %H:%M")
    except (TypeError, ValueError):
        return None
    return (
        "--- Original Message ---\n"
        f"From: {original.get('from_addr', '')}\n"
        f"Date: {formatted_date}\n"
        f"Subject: {original.get('subject', '')}\n\n"
        f"{normalize_newlines(original.get('body_text'))}"
    )

def authored_body(value, originals):
    body = normalize_newlines(value)
    for original in originals:
        quote = service_quote(original)
        suffix = f"\n\n{quote}" if quote is not None else None
        if suffix and body.endswith(suffix):
            return body[:-len(suffix)]
    return body

def canonical_body(value):
    return " ".join(str(value or "").replace("1,420", "1420").split())

def recipient(email):
    return str(email.get("to_addr", "")).strip().lower()

def attachment_names(email):
    attachments = email.get("attachments", [])
    if not isinstance(attachments, list):
        return set()
    names = set()
    for attachment in attachments:
        if isinstance(attachment, dict):
            name = attachment.get("filename") or attachment.get("name")
            if name:
                names.add(str(name).strip().lower())
        elif isinstance(attachment, str):
            names.add(Path(attachment).name.lower())
    return names

def verify(workspace_path, external_services_path=None):
