    sent_emails = [e for e in emails if isinstance(e, dict) and str(e.get("folder", "")).lower() == "sent"]
    maria_originals = [
        e for e in emails
        if isinstance(e, dict)
        and str(e.get("folder", "")).lower() != "sent"
        and str(e.get("from_addr", "")).strip().lower() == "m.torres@crestwood.edu"
        and recipient(e) == "hr@crestwood.edu"
        and str(e.get("subject", "")).strip().lower() == "fmla leave request"
    ]
    torres_emails = [e for e in sent_emails if recipient(e) == "m.torres@crestwood.edu"]
